1	package com.example.starter.service;
2	
3	import java.time.Clock;
4	import java.time.Instant;
5	import java.time.LocalDate;
6	import java.time.LocalDateTime;
7	import java.time.ZoneOffset;
8	import java.util.List;
9	
10	import com.example.starter.domain.ChainAction;
11	import com.example.starter.domain.MaintenanceResult;
12	import com.example.starter.domain.RescueStatus;
13	import com.example.starter.domain.StopReason;
14	import com.example.starter.error.ApiException;
15	import com.example.starter.service.ElevatorService.ElevatorRow;
16	import com.example.starter.web.dto.ApiDtos.MaintenanceRequest;
17	import com.example.starter.web.dto.ApiDtos.MaintenanceView;
18	import org.springframework.http.ResponseEntity;
19	import org.springframework.jdbc.core.JdbcTemplate;
20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	
23	/**
24	 * 维保台账：周期 15 日（UTC 日界），恰第 15 日完成合规；
25	 * 逾期锁定电梯并列入重点监察；结案后迟到维保仅记迟到事件。
26	 */
27	@Service
28	public class MaintenanceService {
29	
30	    /** 维保周期（日） */
31	    static final long CYCLE_DAYS = 15;
32	
33	    private final JdbcTemplate jdbc;
34	    private final ElevatorService elevatorService;
35	    private final IdempotencyService idempotency;
36	    private final Clock clock;
37	
38	    public MaintenanceService(JdbcTemplate jdbc, ElevatorService elevatorService,
39	                              IdempotencyService idempotency, Clock clock) {
40	        this.jdbc = jdbc;
41	        this.elevatorService = elevatorService;
42	        this.idempotency = idempotency;
43	        this.clock = clock;
44	    }
45	
46	    public ResponseEntity<String> register(MaintenanceRequest req) {
47	        String fp = Fingerprints.of("scope=MAINTENANCE", "requestId=" + req.requestId(),
48	                "elevatorId=" + req.elevatorId(), "performedDay=" + req.performedDay(),
49	                "rescueRequestId=" + req.rescueRequestId(), "note=" + req.note());
50	        return idempotency.handle("MAINTENANCE", req.requestId(), fp, () -> doRegister(req));
51	    }
52	
53	    private MaintenanceView doRegister(MaintenanceRequest req) {
54	        ElevatorRow ev = elevatorService.lockElevator(req.elevatorId());
