1	package com.example.starter.service;
2	
3	import java.util.List;
4	import java.util.function.Supplier;
5	
6	import com.example.starter.error.ApiException;
7	import com.fasterxml.jackson.core.JsonProcessingException;
8	import com.fasterxml.jackson.databind.ObjectMapper;
9	import org.springframework.dao.DuplicateKeyException;
10	import org.springframework.http.MediaType;
11	import org.springframework.http.ResponseEntity;
12	import org.springframework.jdbc.core.JdbcTemplate;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.support.TransactionTemplate;
15	
16	/**
17	 * 幂等受理：同一 scope 下 requestId 唯一。
18	 * 同键同参返回首次受理结果；同键异参返回 409 且不改变业务状态；
19	 * 并发同键由主键约束仲裁，失败方回读后按首次结果返回。
20	 */
21	@Service
22	public class IdempotencyService {
23	
24	    private final JdbcTemplate jdbc;
25	    private final TransactionTemplate tx;
26	    private final ObjectMapper objectMapper;
27	
28	    public IdempotencyService(JdbcTemplate jdbc, TransactionTemplate tx, ObjectMapper objectMapper) {
29	        this.jdbc = jdbc;
30	        this.tx = tx;
31	        this.objectMapper = objectMapper;
32	    }
33	
34	    private record Stored(int status, String fingerprint, String body) {
35	    }
36	
37	    /**
38	     * 在单事务内执行业务动作并落幂等记录；返回首次结果的 JSON 报文。
39	     *
40	     * @param scope       业务边界（REPORT/DISPATCH/CLOSE/MAINTENANCE）
41	     * @param requestId   幂等键
42	     * @param fingerprint 覆盖 requestId 与全部业务字段的指纹
43	     * @param business    业务动作，返回将被序列化为响应报文的对象
44	     */
45	    public ResponseEntity<String> handle(String scope, String requestId, String fingerprint,
46	                                         Supplier<Object> business) {
47	        Stored existing = find(scope, requestId);
48	        if (existing != null) {
49	            return replay(existing, fingerprint);
50	        }
51	        try {
52	            return tx.execute(status -> {
53	                Object result = business.get();
54	                String body = toJson(result);
55	                jdbc.update("INSERT INTO idempotency_record(scope, request_id, fingerprint, response_status, response_body) "
56	                                + "VALUES (?,?,?,?,?)",
57	                        scope, requestId, fingerprint, 200, body);
58	                return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).body(body);
59	            });
60	        } catch (DuplicateKeyException e) {
61	            // 并发同键：本事务已回滚，回读胜出方的首次结果
62	            Stored winner = find(scope, requestId);
63	            if (winner != null) {
64	                return replay(winner, fingerprint);
65	            }
66	            // 非幂等键唯一约束冲突（如电梯进行中救援占坑位）
67	            throw ApiException.conflict("STATE_CONFLICT", "并发请求冲突：同一电梯已存在进行中的救援单或重复提交");
68	        }
69	    }
70	
71	    private ResponseEntity<String> replay(Stored stored, String fingerprint) {
72	        if (!stored.fingerprint().equals(fingerprint)) {
73	            throw ApiException.conflict("IDEMPOTENCY_CONFLICT", "相同 requestId 提交了不同的业务参数，已拒绝且未改变状态");
74	        }
75	        return ResponseEntity.status(stored.status()).contentType(MediaType.APPLICATION_JSON).body(stored.body());
76	    }
77	
78	    private Stored find(String scope, String requestId) {
79	        List<Stored> rows = jdbc.query(
80	                "SELECT response_status, fingerprint, response_body FROM idempotency_record WHERE scope=? AND request_id=?",
81	                (rs, i) -> new Stored(rs.getInt(1), rs.getString(2), rs.getString(3)),
82	                scope, requestId);
83	        return rows.isEmpty() ? null : rows.get(0);
84	    }
85	
86	    /** 是否已存在该键的受理记录（业务预检用，并发同键时避免误判状态冲突）。 */
87	    public boolean exists(String scope, String requestId) {
88	        Integer n = jdbc.queryForObject(
89	                "SELECT COUNT(*) FROM idempotency_record WHERE scope=? AND request_id=?",
90	                Integer.class, scope, requestId);
91	        return n != null && n > 0;
92	    }
93	
94	    private String toJson(Object result) {
95	        try {
96	            return objectMapper.writeValueAsString(result);
97	        } catch (JsonProcessingException e) {
98	            throw new IllegalStateException("响应序列化失败", e);
99	        }
100	    }
101	}
