        long r1 = report("T30-r1", e1, T0).id();
        assertEquals(200, dispatch("T30-d1", r1, List.of(s1, s2)).status());
        Resp arrived = arrive(r1, T0.plusSeconds(30 * 60));
        assertEquals(200, arrived.status());
